		/** 
		 * Tests creating a new DataBreach.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a DataBreach");

			StringBuilder msg = new StringBuilder( "-- Failed to create a DataBreach" );

			try {            
				DataBreach entity = DataBreachService.getDataBreachInstance().createDataBreach( generateNewEntity() );
				thePrimaryKey = entity.getDataBreachId();
				LOGGER.info( "-- Successfully created a DataBreach with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a DataBreach. 
		 */
		public DataBreach testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created DataBreach" );

			DataBreach entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read DataBreach with primary key" );
			msg.append( thePrimaryKey );
			
			DataBreachFetchOneSummary fetchOneSummary = new DataBreachFetchOneSummary( thePrimaryKey );

			try {
				entity = DataBreachService.getDataBreachInstance().getDataBreach( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found DataBreach " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a DataBreach.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a DataBreach." );

			StringBuilder msg = new StringBuilder( "Failed to update a DataBreach : " );        
			DataBreach entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created DataBreach." );

				// for use later on...
				thePrimaryKey = entity.getDataBreachId();

				DataBreachService proxy = DataBreachService.getDataBreachInstance();            
				proxy.updateDataBreach( entity );   

				LOGGER.info( "-- Successfully saved DataBreach - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a DataBreach.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created DataBreach." );

			try{
			    DataBreach entity = testRead(); 
				DataBreachService.getDataBreachInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted DataBreach with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete DataBreach with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all DataBreachs.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of DataBreachs:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all DataBreach : " );        
			List<DataBreach> collection  = null;

			try {
				// call the static get method on the DataBreachService
				collection = DataBreachService.getDataBreachInstance().getAllDataBreach();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					DataBreach entity = null;            
					Iterator<DataBreach> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getDataBreachId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

